def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'
    me = [h[0] for h in history]
    op = [h[1] for h in history]
    my_last, opp_last = history[-1]
    opp_def = op.count('D')
    my_def = me.count('D')
    # Detect a pure or near-pure defector (received CD or DD early).
    if n >= 6 and opp_def >= n - 1:
        return 'D'
    # Endgame: if opponent has been mostly defecting, defect hard.
    if n >= 90:
        if opp_def * 2 > n:
            return 'D'
        if opp_def == 0:
            return 'C'
    # Early: short cooperation probe, respond to immediate openings.
    if n < 4:
        if opp_last == 'D':
            return 'D'
        return 'C'
    # Look at recent window.
    w = 8 if n >= 8 else n
    rec = op[-w:]
    rec_def = rec.count('D')
    rec_c = w - rec_def
    # Opponent cooperates a lot.
    if opp_def == 0:
        # Perfect cooperator: mostly defect, but sprinkle C to avoid triggering
        # a conditional defector's punishment. Since opp_def==0 for n rounds,
        # they are likely always-C. Exploit heavily but not blindly.
        if n >= 100:
            return 'C'
        if rng.random() < 0.85:
            return 'D'
        return 'C'
    if rec_def == 0 and opp_def <= 2:
        # Nearly cooperative: exploit sometimes.
        if rng.random() < 0.35:
            return 'D'
        return 'C'
    # Strong defector: defect (with rare forgiveness probes).
    if rec_def * 2 >= w:
        if rec_def == w or opp_def * 3 > n * 2:
            return 'D'
        if opp_last == 'C' and rng.random() < 0.3:
            return 'C'
        return 'D'
    # Tit-for-tat core with forgiveness for mostly-cooperative opponents.
    if opp_last == 'D':
        # Count consecutive opponent defections at end.
        cs = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 'D':
                cs += 1
            else:
                break
        # Forgive quickly if opponent has generally cooperated.
        if opp_def * 4 <= n:
            if cs == 1:
                if rng.random() < 0.5:
                    return 'C'
                return 'D'
            if cs == 2 and rng.random() < 0.3:
                return 'C'
        # If we defected last round too, try to break the DD loop.
        if my_last == 'D':
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        return 'D'
    # Opponent cooperated last round.
    if my_last == 'D':
        # Repair after our defection.
        return 'C'
    if opp_def * 5 < n:
        return 'C'
    if rng.random() < 0.1:
        return 'D'
    return 'C'
